<?php
namespace App\Services\Inventory;
use App\Models\{InventoryItem,PosOrderItem,StockMovement};use App\Services\Procurement\StoreStockService;use Illuminate\Support\Facades\DB;use RuntimeException;
class InventoryService{
 public function __construct(private ?StoreStockService $storeStock=null){}
 public function adjust(InventoryItem $item,float $quantity,string $type,?int $userId=null,?string $notes=null,?object $source=null):StockMovement{return DB::transaction(function()use($item,$quantity,$type,$userId,$notes,$source){$item=InventoryItem::query()->lockForUpdate()->findOrFail($item->id);$new=(float)$item->quantity_on_hand+$quantity;if($new<0)throw new RuntimeException("Insufficient stock for {$item->name}.");$item->update(['quantity_on_hand'=>$new]);return StockMovement::create(['property_id'=>$item->property_id,'inventory_item_id'=>$item->id,'type'=>$type,'quantity'=>$quantity,'unit_cost'=>$item->average_cost,'balance_after'=>$new,'source_type'=>$source?get_class($source):null,'source_id'=>$source?->id,'notes'=>$notes,'created_by'=>$userId]);});}
 private function consume(InventoryItem $item,float $quantity,string $type,?int $userId,?string $notes,PosOrderItem $orderItem):void{$store=$orderItem->order?->outlet?->store;if($store&&$this->storeStock){$this->storeStock->move($store,$item,$quantity,$type,$userId,$notes,$orderItem,null,$orderItem->order?->order_number);return;}$this->adjust($item,$quantity,$type,$userId,$notes,$orderItem);}
 public function consumeForOrderItem(PosOrderItem $orderItem,?int $userId=null):void{DB::transaction(function()use($orderItem,$userId){$orderItem=PosOrderItem::with(['order.outlet.store','menuItem.recipe.ingredients.inventoryItem','menuItem.inventoryItem'])->lockForUpdate()->findOrFail($orderItem->id);if($orderItem->stock_deducted_at||$orderItem->kitchen_status==='cancelled')return;$menu=$orderItem->menuItem;if(!$menu){$orderItem->update(['stock_deducted_at'=>now()]);return;}$qty=(float)$orderItem->quantity;if($menu->recipe){$yield=max(.0001,(float)$menu->recipe->yield_quantity);foreach($menu->recipe->ingredients as $ingredient){$consume=-1*((float)$ingredient->quantity/$yield)*$qty;$this->consume($ingredient->inventoryItem,$consume,'recipe_consumption',$userId,"POS {$orderItem->order?->order_number}: {$orderItem->item_name}",$orderItem);}}elseif($menu->inventoryItem&&$menu->inventoryItem->track_stock&&(float)$menu->stock_quantity_per_sale>0){$this->consume($menu->inventoryItem,-1*((float)$menu->stock_quantity_per_sale*$qty),'sale',$userId,"POS item {$orderItem->item_name}",$orderItem);}$orderItem->update(['stock_deducted_at'=>now()]);});}
}
